mapper.select:
SELECT
    AVG(final_price) as avg_final_price,
    AVG(base_price) as avg_base_price,
    AVG(total_discount) as avg_discount,
    COUNT(*) as total_calculations,
    MIN(final_price) as min_price,
    MAX(final_price) as max_price
FROM pms_pricing_calculations
WHERE del_flag = '0'
  AND tenant_id = #{tenantId}
  AND dept_id = #{deptId}
  AND room_type_id = #{roomTypeId}
  AND check_in_date BETWEEN #{startDate} AND #{endDate}

mapper.delete:
DELETE FROM pms_pricing_calculations
WHERE calculation_time < #{beforeDate}
  AND is_final_booking = 0
